render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#speedo-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const maxSpeed = Math.max(40, params.max_speed || 240);
const autoAnimate = params.auto_animate === true;
const animSpeed = params.anim_speed || 1.0;
const staticSpeed = Math.min(Math.max(params.speed !== undefined ? params.speed : 120, 0), maxSpeed);

// Cálculo de velocidad (Estática vs Animada)
let currentSpeed = staticSpeed;
if (autoAnimate) {
  const cycle = (Math.sin(time * animSpeed * 0.8 - Math.PI / 2) + 1) / 2;
  currentSpeed = cycle * maxSpeed;
}

const redlineStartPct = (params.redline_start || 80) / 100;
const scale = params.gauge_scale || 1.0;
const centerYOffset = params.center_y || 0;

const showBorder = params.show_border !== false;
const showDigital = params.show_digital !== false;
const showActiveArc = params.show_active_arc !== false;

const needleColor = params.needle_color || '#FF3344';
const accentColor = params.accent_color || '#00E5FF';
const bgColor = params.bg_color || '#0B0E14';

// Posicionamiento
const cx = width / 2;
const cy = height / 2 + centerYOffset;
const radius = Math.min(width, height) * 0.38 * scale;

// Fondo general
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

// Ángulos de barrido (135° a 405° = 270° totales)
const startAngle = Math.PI * 0.75;
const endAngle = Math.PI * 2.25;
const sweepAngle = endAngle - startAngle;

// 1. MARCO EXTERIOR Y BISEL
if (showBorder) {
  c.save();
  const outerGrad = c.createRadialGradient(cx, cy, radius * 0.95, cx, cy, radius * 1.15);
  outerGrad.addColorStop(0, '#1E2533');
  outerGrad.addColorStop(0.5, '#3A4659');
  outerGrad.addColorStop(1, '#0F131C');

  c.beginPath();
  c.arc(cx, cy, radius * 1.14, 0, Math.PI * 2);
  c.fillStyle = outerGrad;
  c.fill();

  c.beginPath();
  c.arc(cx, cy, radius * 1.02, 0, Math.PI * 2);
  c.fillStyle = '#10141D';
  c.fill();
  c.restore();
}

// Fondo del dial interior
const dialGrad = c.createRadialGradient(cx, cy, 0, cx, cy, radius);
dialGrad.addColorStop(0, '#151A24');
dialGrad.addColorStop(1, '#0B0E14');
c.beginPath();
c.arc(cx, cy, radius, 0, Math.PI * 2);
c.fillStyle = dialGrad;
c.fill();

// 2. ARCO DE ZONA ROJA (Redline)
const redAngleStart = startAngle + sweepAngle * redlineStartPct;
c.save();
c.beginPath();
c.arc(cx, cy, radius * 0.86, redAngleStart, endAngle);
c.strokeStyle = '#FF2A4B';
c.lineWidth = radius * 0.06;
c.globalAlpha = 0.85;
c.stroke();
c.restore();

// 3. ARCO DE VELOCIDAD ACTIVA
const speedRatio = currentSpeed / maxSpeed;
const engineJitter = currentSpeed > 0 ? (Math.sin(time * 40) * 0.003 * (currentSpeed / maxSpeed)) : 0;
const needleAngle = startAngle + speedRatio * sweepAngle + engineJitter;

if (showActiveArc && speedRatio > 0) {
  c.save();
  c.beginPath();
  c.arc(cx, cy, radius * 0.86, startAngle, needleAngle);
  c.strokeStyle = accentColor;
  c.lineWidth = radius * 0.06;
  c.shadowColor = accentColor;
  c.shadowBlur = 12;
  c.globalAlpha = 0.7;
  c.stroke();
  c.restore();
}

// 4. TICKS Y NÚMEROS
const stepVal = maxSpeed <= 160 ? 10 : 20;

for (let i = 0; i <= maxSpeed; i += stepVal / 2) {
  const isMajor = (i % stepVal === 0);
  const ratio = i / maxSpeed;
  const angle = startAngle + ratio * sweepAngle;

  const innerR = radius * (isMajor ? 0.70 : 0.78);
  const outerR = radius * 0.84;

  const x1 = cx + Math.cos(angle) * innerR;
  const y1 = cy + Math.sin(angle) * innerR;
  const x2 = cx + Math.cos(angle) * outerR;
  const y2 = cy + Math.sin(angle) * outerR;

  const isRed = ratio >= redlineStartPct;

  c.save();
  c.beginPath();
  c.moveTo(x1, y1);
  c.lineTo(x2, y2);
  c.strokeStyle = isRed ? '#FF2A4B' : (isMajor ? '#FFFFFF' : accentColor);
  c.lineWidth = isMajor ? Math.max(2, radius * 0.02) : Math.max(1, radius * 0.008);
  c.globalAlpha = isMajor ? 0.9 : 0.35;
  if (isMajor && !isRed) {
    c.shadowColor = accentColor;
    c.shadowBlur = 4;
  }
  c.stroke();
  c.restore();

  if (isMajor) {
    const textR = radius * 0.56;
    const tx = cx + Math.cos(angle) * textR;
    const ty = cy + Math.sin(angle) * textR;

    c.save();
    c.font = `bold ${Math.round(radius * 0.095)}px sans-serif`;
    c.fillStyle = isRed ? '#FF5566' : '#E2E8F0';
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText(i.toString(), tx, ty);
    c.restore();
  }
}

// 5. PANTALLA DIGITAL
if (showDigital) {
  const digY = cy + radius * 0.42;
  const boxW = radius * 0.65;
  const boxH = radius * 0.28;

  c.save();
  c.fillStyle = '#06080D';
  c.strokeStyle = accentColor;
  c.lineWidth = 1.5;
  c.globalAlpha = 0.85;
  c.beginPath();
  c.roundRect(cx - boxW / 2, digY - boxH / 2, boxW, boxH, 8);
  c.fill();
  c.stroke();

  c.globalAlpha = 1.0;
  c.font = `bold ${Math.round(radius * 0.17)}px monospace`;
  c.fillStyle = accentColor;
  c.shadowColor = accentColor;
  c.shadowBlur = 8;
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(Math.round(currentSpeed).toString(), cx, digY - radius * 0.02);

  c.font = `bold ${Math.round(radius * 0.06)}px sans-serif`;
  c.fillStyle = '#64748B';
  c.shadowBlur = 0;
  c.fillText('KM/H', cx, digY + radius * 0.09);
  c.restore();
}

// 6. AGUJA
c.save();
c.translate(cx, cy);
c.rotate(needleAngle);

c.shadowColor = 'rgba(0, 0, 0, 0.6)';
c.shadowBlur = 10;
c.shadowOffsetX = 4;
c.shadowOffsetY = 4;

c.fillStyle = needleColor;
c.beginPath();
c.moveTo(-radius * 0.12, 0);
c.lineTo(0, -radius * 0.035);
c.lineTo(radius * 0.80, 0);
c.lineTo(0, radius * 0.035);
c.closePath();
c.fill();

c.fillStyle = '#FFFFFF';
c.globalAlpha = 0.3;
c.beginPath();
c.moveTo(0, -radius * 0.015);
c.lineTo(radius * 0.75, 0);
c.lineTo(0, radius * 0.015);
c.closePath();
c.fill();

c.restore();

// Capuchón central
c.save();
c.translate(cx, cy);

c.beginPath();
c.arc(0, 0, radius * 0.13, 0, Math.PI * 2);
c.fillStyle = '#121721';
c.fill();
c.strokeStyle = needleColor;
c.lineWidth = 2.5;
c.stroke();

c.beginPath();
c.arc(0, 0, radius * 0.05, 0, Math.PI * 2);
c.fillStyle = '#E2E8F0';
c.fill();

c.restore();
